<div class="page-head"><div><span class="eyebrow"><?=e($business['name'])?></span><h1>Business Settings</h1><p>Manage business branding and reporting information.</p></div></div><div class="settings-grid"><section class="panel"><h2>Business Profile</h2><dl class="detail-list"><div><dt>Name</dt><dd><?=e($business['name'])?></dd></div><div><dt>Contact</dt><dd><?=e($business['contact_email']?:'Not set')?></dd></div><div><dt>Status</dt><dd><span class="status status-<?=e($business['status'])?>"><?=e(ucfirst($business['status']))?></span></dd></div></dl><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="settings_action" value="timezone"><label>Reporting timezone<span>All report dates and converted peak times use this timezone.</span><select name="timezone" required><?php foreach(DateTimeZone::listIdentifiers() as $tz):?><option value="<?=e($tz)?>" <?=$tz===$business['timezone']?'selected':''?>><?=e($tz)?></option><?php endforeach;?></select></label><button class="btn btn-primary" type="submit">Save Timezone</button></form></section><section class="panel"><h2>Business Logo</h2><p>Upload a transparent or white-background logo. It will appear automatically on dashboards and exported reports.</p><?php if(!empty($business['logo_path'])):?><div class="business-logo-preview"><img src="<?=base_url($business['logo_path'])?>" alt="<?=e($business['name'])?> logo"></div><?php endif;?><form method="post" enctype="multipart/form-data" class="stack-form"><?=csrf_field()?><input type="hidden" name="settings_action" value="logo"><label>Logo file <span>PNG, JPG, or WebP · maximum 2 MB</span><input type="file" name="business_logo" accept="image/png,image/jpeg,image/webp" required></label><button class="btn btn-primary" type="submit">Upload Logo</button></form></section><section class="panel"><h2>Appearance</h2><p>Use the floating Theme button to switch between light and dark modes.</p><div class="theme-preview"><i style="background:<?=e($business['primary_color'])?>"></i><i style="background:<?=e($business['accent_color'])?>"></i></div></section></div>